    async def initialize(self) -> None:
        await asyncio.to_thread(self.initialize_sync)

    def _execute_sync(self, sql: str, params: tuple=()) -> None:
        with self._connect() as conn:
            conn.execute(sql, params)
            conn.commit()

    def _one_sync(self, sql: str, params: tuple=()) -> dict | None:
        with self._connect() as conn:
            row = conn.execute(sql, params).fetchone()
            return dict(row) if row else None

    def _all_sync(self, sql: str, params: tuple=()) -> list[dict]:
        with self._connect() as conn:
            return [dict(row) for row in conn.execute(sql, params).fetchall()]

    async def execute(self, sql: str, params: tuple=()) -> None:
        await asyncio.to_thread(self._execute_sync, sql, params)

    async def one(self, sql: str, params: tuple=()) -> dict | None:
        return await asyncio.to_thread(self._one_sync, sql, params)

    async def all(self, sql: str, params: tuple=()) -> list[dict]:
        return await asyncio.to_thread(self._all_sync, sql, params)

    async def get_setting(self, user_id: str, key: str, default: str='') -> str:
        row = await self.one('SELECT value FROM settings WHERE user_id=? AND key=?', (user_id, key))
        return str(row['value']) if row else default

    async def set_setting(self, user_id: str, key: str, value: str) -> None:
        await self.execute('INSERT INTO settings(user_id,key,value,updated_at) VALUES(?,?,?,?) ON CONFLICT(user_id,key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at', (user_id, key, value, _now()))

    @staticmethod
    def _tool_state_fingerprint(catalog: list[dict], inventory: list[dict], active_keys: list[str], source_summary: dict) -> str:

        def compact(items: list[dict], fields: tuple[str, ...]) -> list[dict]:
            result = []
            for item in items:
                if not isinstance(item, dict):
                    continue
                result.append({key: item.get(key) for key in fields if key in item})
            result.sort(key=lambda value: tuple((str(value.get(key) or '') for key in fields)))
            return result
        payload = {'catalog': compact(catalog, ('function_name', 'declared_name', 'tool_id', 'capability', 'provider', 'active_in_chat', 'availability')), 'inventory': compact(inventory, ('registry_key', 'function_name', 'declared_name', 'tool_id', 'source_kind', 'kind', 'active_in_chat', 'invocable', 'availability')), 'active_keys': sorted({str(value) for value in active_keys if str(value or '').strip()}), 'source_summary': source_summary if isinstance(source_summary, dict) else {}}
        return hashlib.sha256(_json_dumps(payload).encode('utf-8', errors='replace')).hexdigest()

    async def set_session_tools(self, user_id: str, session_id: str, catalog: list[dict], *, inventory: list[dict] | None=None, source_summary: dict | None=None, active_keys: list[str] | None=None, context: dict | None=None) -> dict:
        safe_catalog = [item for item in catalog or [] if isinstance(item, dict)][:512]
        safe_inventory = [item for item in inventory or [] if isinstance(item, dict)][:1500]
        safe_summary = source_summary if isinstance(source_summary, dict) else {}
        safe_active = [str(value) for value in active_keys or [] if str(value or '').strip()][:1500]
        safe_context = context if isinstance(context, dict) else {}
        fingerprint = self._tool_state_fingerprint(safe_catalog, safe_inventory, safe_active, safe_summary)
        previous = await self.one('SELECT revision,fingerprint FROM session_tools WHERE user_id=? AND session_id=?', (user_id, session_id))
        changed = not previous or str(previous.get('fingerprint') or '') != fingerprint
        revision = int((previous or {}).get('revision') or 0) + (1 if changed else 0)
        now = _now()
        await self.execute('INSERT INTO session_tools(session_id,user_id,catalog_json,inventory_json,source_summary_json,active_keys_json,context_json,revision,fingerprint,last_turn_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(session_id) DO UPDATE SET user_id=excluded.user_id,catalog_json=excluded.catalog_json,inventory_json=excluded.inventory_json,source_summary_json=excluded.source_summary_json,active_keys_json=excluded.active_keys_json,context_json=excluded.context_json,revision=excluded.revision,fingerprint=excluded.fingerprint,last_turn_at=excluded.last_turn_at,updated_at=excluded.updated_at', (session_id, user_id, _json_dumps(safe_catalog), _json_dumps(safe_inventory), _json_dumps(safe_summary), _json_dumps(safe_active), _json_dumps(safe_context), revision, fingerprint, now, now))
        return {'changed': changed, 'revision': revision, 'fingerprint': fingerprint, 'updated_at': now, 'recommended_count': len(safe_catalog), 'inventory_count': len(safe_inventory), 'active_count': len(safe_active)}

    async def get_session_tool_state(self, user_id: str, session_id: str) -> dict:
        row = await self.one('SELECT catalog_json,inventory_json,source_summary_json,active_keys_json,context_json,revision,fingerprint,last_turn_at,updated_at FROM session_tools WHERE user_id=? AND session_id=?', (user_id, session_id))
        if not row:
            return {'catalog': [], 'inventory': [], 'source_summary': {}, 'active_keys': [], 'context': {}, 'revision': 0, 'fingerprint': '', 'last_turn_at': 0, 'updated_at': 0}
        catalog = _safe_json_loads(row.get('catalog_json', '[]'), [])
        inventory = _safe_json_loads(row.get('inventory_json', '[]'), [])
        summary = _safe_json_loads(row.get('source_summary_json', '{}'), {})
        active = _safe_json_loads(row.get('active_keys_json', '[]'), [])
        context = _safe_json_loads(row.get('context_json', '{}'), {})
        return {'catalog': catalog if isinstance(catalog, list) else [], 'inventory': inventory if isinstance(inventory, list) else [], 'source_summary': summary if isinstance(summary, dict) else {}, 'active_keys': active if isinstance(active, list) else [], 'context': context if isinstance(context, dict) else {}, 'revision': int(row.get('revision') or 0), 'fingerprint': str(row.get('fingerprint') or ''), 'last_turn_at': int(row.get('last_turn_at') or 0), 'updated_at': int(row.get('updated_at') or 0)}

    async def get_session_tools(self, user_id: str, session_id: str) -> list[dict]:
        return (await self.get_session_tool_state(user_id, session_id))['catalog']

    @staticmethod
    def _tool_action_prompt_hash(prompt: str) -> str:
        normalized = unicodedata.normalize('NFKC', str(prompt or ''))
        normalized = _strip_tool_action_reference(normalized)
        normalized = _strip_escaped_vut_controls(normalized)
        normalized = normalized.replace('\xa0', ' ').replace('\u200b', '').replace('\ufeff', '')
        normalized = normalized.replace('\r\n', '\n').replace('\r', '\n')
        normalized = re.sub('\\\\([_*`#\\[\\]()])', '\\1', normalized)
        normalized = re.sub('\\s+', ' ', normalized).strip().casefold()
        return hashlib.sha256(normalized.encode('utf-8', errors='replace')).hexdigest()

    @staticmethod
    def _looks_like_canvas_tool_prompt(prompt: str) -> bool:
        folded = unicodedata.normalize('NFKC', str(prompt or '')).casefold()
        exact_execution = 'nástroj spustí vut ai tutor přímo' in folded
        current_contract = all((heading in folded for heading in ('studijní scénář', 'závazně zvolený nástroj', 'pravidla provedení')))
        legacy_contract = 'požadovaný alternativní pohled' in folded
        return exact_execution and (current_contract or legacy_contract)

    def _queue_tool_action_sync(self, user_id: str, chat_id: str, session_id: str, prompt: str, payload: dict, ttl_seconds: int) -> str:
        now = _now()
        action_id = str(uuid.uuid4())
        prompt_hash = self._tool_action_prompt_hash(prompt)
        with self._connect() as conn:
            conn.execute('DELETE FROM pending_tool_actions WHERE expires_at<? OR (consumed_at>0 AND consumed_at<?)', (now, now - 3600))
            conn.execute('DELETE FROM pending_tool_actions WHERE user_id=? AND session_id=? AND consumed_at=0', (user_id, str(session_id or '')))
            conn.execute('INSERT INTO pending_tool_actions(id,user_id,chat_id,session_id,prompt_sha256,payload_json,created_at,expires_at,consumed_at) VALUES(?,?,?,?,?,?,?,?,0)', (action_id, user_id, str(chat_id or ''), session_id, prompt_hash, _json_dumps(payload), now, now + max(120, min(int(ttl_seconds), 3600))))
            conn.commit()
        return action_id

    async def queue_tool_action(self, user_id: str, chat_id: str, session_id: str, prompt: str, payload: dict, ttl_seconds: int=1800) -> str:
        return await asyncio.to_thread(self._queue_tool_action_sync, user_id, chat_id, session_id, prompt, payload, ttl_seconds)

    def _consume_tool_action_sync(self, user_id: str, chat_id: str, prompts: list[str], session_id: str='', action_id: str='') -> dict | None:
        visible_prompts = [str(value or '') for value in prompts if str(value or '').strip()]
        hashes = list(dict.fromkeys((self._tool_action_prompt_hash(value) for value in visible_prompts)))[:12]
        if not hashes and not action_id:
            return None
        now = _now()
        row = None
        matched_by = ''
        with self._connect() as conn:
            if action_id:
                row = conn.execute(
                    "SELECT * FROM pending_tool_actions WHERE id=? AND user_id=? AND consumed_at=0 AND expires_at>=? AND (chat_id='' OR ?='' OR chat_id=?) AND (session_id='' OR ?='' OR session_id=?) LIMIT 1",
                    (str(action_id), user_id, now, str(chat_id or ''), str(chat_id or ''), str(session_id or ''), str(session_id or '')),
                ).fetchone()
                if row:
                    matched_by = 'action-id'
            if not row and hashes:
                placeholders = ','.join(('?' for _ in hashes))
                strict_sql = f"SELECT * FROM pending_tool_actions WHERE user_id=? AND consumed_at=0 AND expires_at>=? AND prompt_sha256 IN ({placeholders}) AND (chat_id='' OR ?='' OR chat_id=?) ORDER BY created_at DESC LIMIT 1"
                strict_params = (user_id, now, *hashes, str(chat_id or ''), str(chat_id or ''))
                fallback_sql = f'SELECT * FROM pending_tool_actions WHERE user_id=? AND consumed_at=0 AND expires_at>=? AND prompt_sha256 IN ({placeholders}) ORDER BY created_at DESC LIMIT 1'
                fallback_params = (user_id, now, *hashes)
                row = conn.execute(strict_sql, strict_params).fetchone()
                if not row:
                    row = conn.execute(fallback_sql, fallback_params).fetchone()
                if row:
                    matched_by = 'prompt-hash'
            if not row and any((self._looks_like_canvas_tool_prompt(value) for value in visible_prompts)):
                if session_id:
                    rows = conn.execute("SELECT * FROM pending_tool_actions WHERE user_id=? AND consumed_at=0 AND expires_at>=? AND (session_id='' OR session_id=?) ORDER BY created_at DESC LIMIT 2", (user_id, now, str(session_id))).fetchall()
                else:
                    rows = conn.execute('SELECT * FROM pending_tool_actions WHERE user_id=? AND consumed_at=0 AND expires_at>=? ORDER BY created_at DESC LIMIT 2', (user_id, now)).fetchall()
                if len(rows) == 1:
                    row = rows[0]
                    matched_by = 'unique-pending-canvas-action'
            if not row:
                return None
            updated = conn.execute('UPDATE pending_tool_actions SET consumed_at=? WHERE id=? AND consumed_at=0', (now, row['id']))
            if updated.rowcount != 1:
                conn.rollback()
                return None
            conn.commit()
            payload = _safe_json_loads(row['payload_json'], {})
            if not isinstance(payload, dict):
                return None
            payload['action_id'] = str(row['id'])
            payload['delivery'] = 'pending-action'
            payload['matched_by'] = matched_by or 'pending-action'
            return payload

    async def consume_tool_action(self, user_id: str, chat_id: str, prompts: list[str], session_id: str='', action_id: str='') -> dict | None:
        return await asyncio.to_thread(self._consume_tool_action_sync, user_id, chat_id, prompts, session_id, action_id)

    def _queue_prompt_binding_sync(self, user_id: str, chat_id: str, session_id: str, prompt: str, kind: str, payload: dict, ttl_seconds: int) -> str:
        now = _now()
        binding_id = str(uuid.uuid4())
        prompt_hash = self._tool_action_prompt_hash(prompt)
        with self._connect() as conn:
            conn.execute('DELETE FROM pending_prompt_bindings WHERE expires_at<? OR (consumed_at>0 AND consumed_at<?)', (now, now - 3600))
            conn.execute('INSERT INTO pending_prompt_bindings(id,user_id,chat_id,session_id,prompt_sha256,kind,payload_json,created_at,expires_at,consumed_at) VALUES(?,?,?,?,?,?,?,?,?,0)', (binding_id, user_id, str(chat_id or ''), session_id, prompt_hash, kind, _json_dumps(payload), now, now + max(30, min(int(ttl_seconds), 600))))
            conn.commit()
        return binding_id

    async def queue_prompt_binding(self, user_id: str, chat_id: str, session_id: str, prompt: str, kind: str, payload: dict, ttl_seconds: int=240) -> str:
        return await asyncio.to_thread(self._queue_prompt_binding_sync, user_id, chat_id, session_id, prompt, kind, payload, ttl_seconds)

    def _consume_prompt_binding_sync(self, user_id: str, chat_id: str, prompts: list[str]) -> dict | None:
        hashes = list(dict.fromkeys((self._tool_action_prompt_hash(value) for value in prompts if str(value or '').strip())))[:12]
        if not hashes:
            return None
        now = _now()
        placeholders = ','.join(('?' for _ in hashes))
        sql = f"SELECT * FROM pending_prompt_bindings WHERE user_id=? AND consumed_at=0 AND expires_at>=? AND prompt_sha256 IN ({placeholders}) AND (chat_id='' OR ?='' OR chat_id=?) ORDER BY created_at DESC LIMIT 1"
        params = (user_id, now, *hashes, str(chat_id or ''), str(chat_id or ''))
        fallback = f'SELECT * FROM pending_prompt_bindings WHERE user_id=? AND consumed_at=0 AND expires_at>=? AND prompt_sha256 IN ({placeholders}) ORDER BY created_at DESC LIMIT 1'
        with self._connect() as conn:
            row = conn.execute(sql, params).fetchone() or conn.execute(fallback, (user_id, now, *hashes)).fetchone()
            if not row:
                return None
            updated = conn.execute('UPDATE pending_prompt_bindings SET consumed_at=? WHERE id=? AND consumed_at=0', (now, row['id']))
            if updated.rowcount != 1:
                conn.rollback()
                return None
            conn.commit()
            payload = _safe_json_loads(row['payload_json'], {})
            if not isinstance(payload, dict):
                payload = {}
            payload.update({'binding_id': str(row['id']), 'binding_kind': str(row['kind'] or '')})
            return payload

    async def consume_prompt_binding(self, user_id: str, chat_id: str, prompts: list[str]) -> dict | None:
        return await asyncio.to_thread(self._consume_prompt_binding_sync, user_id, chat_id, prompts)

    async def save_tool_action_thread(self, user_id: str, chat_id: str, session_id: str, payload: dict, original_prompt: str, question: str, *, thread_id: str='', clarifications: list[str] | None=None, ttl_seconds: int=900) -> str:
        now = _now()
        thread_id = thread_id or str(payload.get('action_id') or uuid.uuid4())
        await self.execute("INSERT INTO tool_action_threads(id,user_id,chat_id,session_id,payload_json,original_prompt,clarifications_json,last_question,state,created_at,updated_at,expires_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET chat_id=excluded.chat_id,session_id=excluded.session_id,payload_json=excluded.payload_json,original_prompt=excluded.original_prompt,clarifications_json=excluded.clarifications_json,last_question=excluded.last_question,state='awaiting_user',updated_at=excluded.updated_at,expires_at=excluded.expires_at", (thread_id, user_id, str(chat_id or ''), session_id, _json_dumps(payload), original_prompt, _json_dumps(clarifications or []), question, 'awaiting_user', now, now, now + max(120, min(int(ttl_seconds), 3600))))
        return thread_id

    @staticmethod
    def _unpack_tool_action_thread(row: dict | None) -> dict | None:
        if not row:
            return None
        payload = _safe_json_loads(row.get('payload_json'), {})
        clarifications = _safe_json_loads(row.get('clarifications_json'), [])
        return {**(payload if isinstance(payload, dict) else {}), 'thread_id': str(row.get('id') or ''), 'original_prompt': str(row.get('original_prompt') or ''), 'clarifications': clarifications if isinstance(clarifications, list) else [], 'last_question': str(row.get('last_question') or ''), 'stored_chat_id': str(row.get('chat_id') or ''), 'stored_session_id': str(row.get('session_id') or '')}

    async def get_awaiting_tool_action(self, user_id: str, chat_id: str, *, thread_ref: str='', allow_recent_fallback: bool=False) -> dict | None:
        """Resolve one pending technical transaction without letting chat-id churn lose it.

        Open WebUI can replace a temporary/new-chat id with the persisted chat id between
        the clarification question and the user's answer.  A visible/hidden workflow token
        is therefore authoritative; exact chat matching is only the second lookup path.
        The final user-wide fallback is accepted only when exactly one unexpired transaction
        exists, so an unrelated conversation can never steal another pending tool action.
        """
        now = _now()
        reference = re.sub('[^0-9a-f-]', '', str(thread_ref or '').casefold())[:36]
        if len(reference.replace('-', '')) >= 8:
            rows = await self.all("SELECT * FROM tool_action_threads WHERE user_id=? AND state='awaiting_user' AND expires_at>=? AND (id=? OR id LIKE ?) ORDER BY updated_at DESC LIMIT 2", (user_id, now, reference, reference + '%'))
            unique = {str(row.get('id') or ''): row for row in rows}
            if len(unique) == 1:
                return self._unpack_tool_action_thread(next(iter(unique.values())))
        if str(chat_id or ''):
            row = await self.one("SELECT * FROM tool_action_threads WHERE user_id=? AND state='awaiting_user' AND expires_at>=? AND (chat_id='' OR chat_id=?) ORDER BY updated_at DESC LIMIT 1", (user_id, now, str(chat_id or '')))
        else:
            row = await self.one("SELECT * FROM tool_action_threads WHERE user_id=? AND state='awaiting_user' AND expires_at>=? AND chat_id='' ORDER BY updated_at DESC LIMIT 1", (user_id, now))
        if row:
            return self._unpack_tool_action_thread(row)
        if allow_recent_fallback:
            rows = await self.all("SELECT * FROM tool_action_threads WHERE user_id=? AND state='awaiting_user' AND expires_at>=? ORDER BY updated_at DESC LIMIT 2", (user_id, now))
            if len(rows) == 1:
                return self._unpack_tool_action_thread(rows[0])
        return None

    async def update_tool_action_thread_clarification(self, user_id: str, thread_id: str, clarification: str) -> None:
        row = await self.one('SELECT clarifications_json FROM tool_action_threads WHERE id=? AND user_id=?', (thread_id, user_id))
        values = _safe_json_loads((row or {}).get('clarifications_json', '[]'), [])
        if not isinstance(values, list):
            values = []
        values.append(str(clarification or '')[:12000])
        await self.execute('UPDATE tool_action_threads SET clarifications_json=?,updated_at=? WHERE id=? AND user_id=?', (_json_dumps(values[-8:]), _now(), thread_id, user_id))

    async def finish_tool_action_thread(self, user_id: str, thread_id: str, state: str='completed') -> None:
        if not thread_id:
            return
        await self.execute('UPDATE tool_action_threads SET state=?,updated_at=? WHERE id=? AND user_id=?', (state, _now(), thread_id, user_id))

    async def register_book(self, user_id: str, knowledge_id: str, file_id: str, title: str, file_sha256: str='') -> dict:
        """Register a book idempotently by raw PDF hash.

        Open WebUI assigns a fresh file_id to every upload, even when bytes are identical.
        VUT AI Tutor therefore treats SHA-256 as the library identity and reuses the first
        canonical book. The duplicate Open WebUI file is not shown in My books and is never
        re-indexed by this plugin.
        """
        now = _now()
        digest = re.sub('[^0-9a-f]', '', str(file_sha256 or '').casefold())[:64]
        row = await self.one('SELECT * FROM books WHERE file_id=?', (file_id,))
        if row:
            if row['user_id'] != user_id:
                raise HTTPException(status_code=403, detail='Kniha patří jinému uživateli.')
            await self.execute("UPDATE books SET title=?,knowledge_id=?,file_sha256=CASE WHEN ?<>'' THEN ? ELSE file_sha256 END,updated_at=? WHERE file_id=?", (title, knowledge_id, digest, digest, now, file_id))
            canonical_id = str(row.get('canonical_file_id') or '')
            if canonical_id:
                canonical = await self.one('SELECT * FROM books WHERE user_id=? AND file_id=?', (user_id, canonical_id))
                if canonical:
                    canonical['deduplicated'] = True
                    canonical['duplicate_file_id'] = file_id
                    await self.set_setting(user_id, 'active_file_id', canonical_id)
                    return canonical
        else:
            canonical = None
            if digest:
                canonical = await self.one("SELECT * FROM books WHERE user_id=? AND file_sha256=? AND canonical_file_id='' ORDER BY updated_at DESC LIMIT 1", (user_id, digest))
            if canonical:
                await self.execute('INSERT INTO books(id,user_id,knowledge_id,file_id,title,content_hash,file_sha256,canonical_file_id,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)', (str(uuid.uuid4()), user_id, knowledge_id, file_id, title, '', digest, canonical['file_id'], now, now))
                await self.execute('UPDATE books SET updated_at=? WHERE file_id=?', (now, canonical['file_id']))
                await self.set_setting(user_id, 'active_file_id', canonical['file_id'])
                canonical = dict(canonical)
                canonical['deduplicated'] = True
                canonical['duplicate_file_id'] = file_id
                return canonical
            await self.execute('INSERT INTO books(id,user_id,knowledge_id,file_id,title,content_hash,file_sha256,canonical_file_id,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)', (str(uuid.uuid4()), user_id, knowledge_id, file_id, title, '', digest, '', now, now))
        await self.set_setting(user_id, 'active_file_id', file_id)
        return await self.one('SELECT * FROM books WHERE file_id=?', (file_id,)) or {}

    async def list_all_books(self, user_id: str) -> list[dict]:
        return await self.all('SELECT * FROM books WHERE user_id=? ORDER BY updated_at DESC', (user_id,))

    async def list_books(self, user_id: str) -> list[dict]:
        rows = await self.all("SELECT * FROM books WHERE user_id=? AND canonical_file_id='' ORDER BY updated_at DESC", (user_id,))
        result: list[dict] = []
        seen_hashes: set[str] = set()
        for row in rows:
            digest = str(row.get('file_sha256') or '')
            if digest and digest in seen_hashes:
                continue
            if digest:
                seen_hashes.add(digest)
            result.append(row)
        return result

    async def get_book(self, user_id: str, file_id: str) -> dict | None:
        row = await self.one('SELECT * FROM books WHERE user_id=? AND file_id=?', (user_id, file_id))
        if row and row.get('canonical_file_id'):
            canonical = await self.one('SELECT * FROM books WHERE user_id=? AND file_id=?', (user_id, row['canonical_file_id']))
            return canonical or row
        return row

    async def update_book_hash(self, user_id: str, file_id: str, content_hash: str) -> None:
        await self.execute('UPDATE books SET content_hash=?,updated_at=? WHERE user_id=? AND file_id=?', (content_hash[:128], _now(), user_id, file_id))

    async def update_book_file_hash(self, user_id: str, file_id: str, file_sha256: str) -> None:
        digest = re.sub('[^0-9a-f]', '', str(file_sha256 or '').casefold())[:64]
        if digest:
            await self.execute('UPDATE books SET file_sha256=?,updated_at=? WHERE user_id=? AND file_id=?', (digest, _now(), user_id, file_id))

    async def mark_duplicate_books(self, user_id: str, canonical_file_id: str, duplicate_file_ids: list[str]) -> None:
        """Collapse historical byte-identical rows without losing study state."""
        duplicate_file_ids = [value for value in dict.fromkeys(duplicate_file_ids) if value and value != canonical_file_id]
        if not duplicate_file_ids:
            return
        now = _now()
        canonical_path = await self.one('SELECT id FROM learning_paths WHERE user_id=? AND book_file_id=?', (user_id, canonical_file_id))
        canonical_analysis = await self.one('SELECT status FROM book_analysis WHERE user_id=? AND file_id=?', (user_id, canonical_file_id))
        for duplicate_id in duplicate_file_ids:
            await self.execute('UPDATE selections SET file_id=? WHERE user_id=? AND file_id=?', (canonical_file_id, user_id, duplicate_id))
            await self.execute('UPDATE activities SET file_id=? WHERE user_id=? AND file_id=?', (canonical_file_id, user_id, duplicate_id))
            for item in await self.all('SELECT * FROM mastery WHERE user_id=? AND file_id=?', (user_id, duplicate_id)):
                await self.execute('INSERT INTO mastery(user_id,file_id,topic_key,topic_name,mastery,evidence_count,updated_at) VALUES(?,?,?,?,?,?,?) ON CONFLICT(user_id,file_id,topic_key) DO UPDATE SET topic_name=excluded.topic_name,mastery=MAX(mastery,excluded.mastery),evidence_count=MAX(evidence_count,excluded.evidence_count),updated_at=MAX(updated_at,excluded.updated_at)', (user_id, canonical_file_id, item['topic_key'], item['topic_name'], item['mastery'], item['evidence_count'], item['updated_at']))
            await self.execute('DELETE FROM mastery WHERE user_id=? AND file_id=?', (user_id, duplicate_id))
            duplicate_path = await self.one('SELECT id FROM learning_paths WHERE user_id=? AND book_file_id=?', (user_id, duplicate_id))
            if duplicate_path and (not canonical_path):
                await self.execute('UPDATE learning_paths SET book_file_id=?,updated_at=? WHERE id=?', (canonical_file_id, now, duplicate_path['id']))
                canonical_path = duplicate_path
            elif duplicate_path:
                await self.execute('DELETE FROM learning_paths WHERE id=?', (duplicate_path['id'],))
            if not canonical_analysis:
                duplicate_analysis = await self.one('SELECT status FROM book_analysis WHERE user_id=? AND file_id=?', (user_id, duplicate_id))
                if duplicate_analysis:
                    await self.execute('UPDATE book_analysis SET file_id=?,updated_at=? WHERE user_id=? AND file_id=?', (canonical_file_id, now, user_id, duplicate_id))
                    canonical_analysis = duplicate_analysis
            await self.execute('UPDATE books SET canonical_file_id=?,updated_at=? WHERE user_id=? AND file_id=?', (canonical_file_id, now, user_id, duplicate_id))
            await self.execute('UPDATE sessions SET file_id=?,updated_at=? WHERE user_id=? AND file_id=?', (canonical_file_id, now, user_id, duplicate_id))
        active = await self.get_setting(user_id, 'active_file_id')
        if active in duplicate_file_ids:
            await self.set_setting(user_id, 'active_file_id', canonical_file_id)

    async def get_analysis(self, user_id: str, file_id: str) -> dict | None:
        row = await self.one('SELECT * FROM book_analysis WHERE user_id=? AND file_id=?', (user_id, file_id))
        if row:
            graph = _safe_json_loads(row.pop('graph_json', '{}'), {})
            fast_graph = _safe_json_loads(row.pop('fast_graph_json', '{}'), {}) or graph
            deep_graph = _safe_json_loads(row.pop('deep_graph_json', '{}'), {})
            row['graph'] = graph or deep_graph or fast_graph
            row['fast_graph'] = fast_graph
            row['deep_graph'] = deep_graph
            row['lexical'] = _safe_json_loads(row.pop('lexical_json', '[]'), [])
            row['toc'] = _safe_json_loads(row.pop('toc_json', '[]'), [])
            row['cache_hit'] = bool(row.get('cache_hit'))
        return row

    async def set_analysis(self, user_id: str, file_id: str, *, status: str, progress: float, stage: str, graph: dict | None=None, fast_graph: dict | None=None, deep_graph: dict | None=None, lexical: list | None=None, toc: list | None=None, analysis_version: int | None=None, source_hash: str | None=None, cache_hit: bool | None=None, deep_status: str | None=None, deep_progress: float | None=None, deep_stage: str | None=None, deep_error: str | None=None, error: str | None=None, started: bool=False, completed: bool=False, deep_started: bool=False, deep_completed: bool=False) -> None:
        existing = await self.get_analysis(user_id, file_id)
        now = _now()
        fast_value = fast_graph if fast_graph is not None else (existing or {}).get('fast_graph') or {}
        deep_value = deep_graph if deep_graph is not None else (existing or {}).get('deep_graph') or {}
        graph_value = graph if graph is not None else (existing or {}).get('graph') or deep_value or fast_value
        lexical_value = lexical if lexical is not None else (existing or {}).get('lexical') or []
        toc_value = toc if toc is not None else (existing or {}).get('toc') or []
        started_at = now if started else (existing or {}).get('started_at')
        completed_at = now if completed else (existing or {}).get('completed_at')
        deep_started_at = now if deep_started else (existing or {}).get('deep_started_at')
        deep_completed_at = now if deep_completed else (existing or {}).get('deep_completed_at')
        version_value = int(analysis_version if analysis_version is not None else (existing or {}).get('analysis_version') or 0)
        source_value = str(source_hash if source_hash is not None else (existing or {}).get('source_hash') or '')[:128]
        cache_value = int(bool(cache_hit if cache_hit is not None else (existing or {}).get('cache_hit') or False))
        deep_status_value = str(deep_status if deep_status is not None else (existing or {}).get('deep_status') or 'not_requested')
        deep_progress_value = float(deep_progress if deep_progress is not None else (existing or {}).get('deep_progress') or 0)
        deep_stage_value = str(deep_stage if deep_stage is not None else (existing or {}).get('deep_stage') or '')
        deep_error_value = deep_error if deep_error is not None else (existing or {}).get('deep_error')
        await self.execute('INSERT INTO book_analysis(user_id,file_id,status,progress,stage,graph_json,fast_graph_json,deep_graph_json,lexical_json,toc_json,analysis_version,source_hash,cache_hit,deep_status,deep_progress,deep_stage,deep_error,error,started_at,completed_at,deep_started_at,deep_completed_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(user_id,file_id) DO UPDATE SET status=excluded.status,progress=excluded.progress,stage=excluded.stage,graph_json=excluded.graph_json,fast_graph_json=excluded.fast_graph_json,deep_graph_json=excluded.deep_graph_json,lexical_json=excluded.lexical_json,toc_json=excluded.toc_json,analysis_version=excluded.analysis_version,source_hash=excluded.source_hash,cache_hit=excluded.cache_hit,deep_status=excluded.deep_status,deep_progress=excluded.deep_progress,deep_stage=excluded.deep_stage,deep_error=excluded.deep_error,error=excluded.error,started_at=COALESCE(excluded.started_at,book_analysis.started_at),completed_at=excluded.completed_at,deep_started_at=COALESCE(excluded.deep_started_at,book_analysis.deep_started_at),deep_completed_at=excluded.deep_completed_at,updated_at=excluded.updated_at', (user_id, file_id, status, max(0.0, min(1.0, float(progress))), stage, _json_dumps(graph_value), _json_dumps(fast_value), _json_dumps(deep_value), _json_dumps(lexical_value), _json_dumps(toc_value), version_value, source_value, cache_value, deep_status_value, max(0.0, min(1.0, deep_progress_value)), deep_stage_value[:500], deep_error_value, error, started_at, completed_at, deep_started_at, deep_completed_at, now))

    async def set_deep_analysis(self, user_id: str, file_id: str, *, status: str, progress: float, stage: str, graph: dict | None=None, error: str | None=None, started: bool=False, completed: bool=False) -> None:
        existing = await self.get_analysis(user_id, file_id)
        if not existing:
            raise RuntimeError('Rychlá mapa musí být vytvořena před hlubší analýzou.')
        active_graph = graph if graph is not None else existing.get('graph') or existing.get('fast_graph') or {}
        await self.set_analysis(user_id, file_id, status=existing.get('status') or 'completed', progress=float(existing.get('progress') or 1), stage=existing.get('stage') or 'Rychlá mapa je připravena', graph=active_graph, fast_graph=existing.get('fast_graph') or {}, deep_graph=graph if graph is not None else existing.get('deep_graph') or {}, lexical=existing.get('lexical') or [], toc=existing.get('toc') or [], analysis_version=int(existing.get('analysis_version') or ANALYSIS_PIPELINE_VERSION), source_hash=existing.get('source_hash') or '', cache_hit=bool(existing.get('cache_hit')), deep_status=status, deep_progress=progress, deep_stage=stage, deep_error=error, error=existing.get('error'), deep_started=started, deep_completed=completed)

    async def get_analysis_cache(self, user_id: str, source_hash: str) -> dict | None:
        if not source_hash:
            return None
        row = await self.one('SELECT * FROM analysis_cache WHERE user_id=? AND source_hash=? AND analysis_version=?', (user_id, source_hash, ANALYSIS_PIPELINE_VERSION))
        if not row:
            return None
        row['fast_graph'] = _safe_json_loads(row.pop('fast_graph_json', '{}'), {})
        row['deep_graph'] = _safe_json_loads(row.pop('deep_graph_json', '{}'), {})
        row['lexical'] = _safe_json_loads(row.pop('lexical_json', '[]'), [])
        row['toc'] = _safe_json_loads(row.pop('toc_json', '[]'), [])
        return row

    async def save_analysis_cache(self, user_id: str, source_hash: str, *, fast_graph: dict, deep_graph: dict | None, lexical: list, toc: list) -> None:
        if not source_hash or not fast_graph:
            return
        existing = await self.get_analysis_cache(user_id, source_hash)
        now = _now()
        deep_value = deep_graph if deep_graph is not None else (existing or {}).get('deep_graph') or {}
        await self.execute('INSERT INTO analysis_cache(user_id,source_hash,analysis_version,fast_graph_json,deep_graph_json,lexical_json,toc_json,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(user_id,source_hash,analysis_version) DO UPDATE SET fast_graph_json=excluded.fast_graph_json,deep_graph_json=excluded.deep_graph_json,lexical_json=excluded.lexical_json,toc_json=excluded.toc_json,updated_at=excluded.updated_at', (user_id, source_hash, ANALYSIS_PIPELINE_VERSION, _json_dumps(fast_graph), _json_dumps(deep_value), _json_dumps(lexical), _json_dumps(toc), int((existing or {}).get('created_at') or now), now))

    async def get_learning_path(self, user_id: str, book_file_id: str) -> dict | None:
        row = await self.one('SELECT * FROM learning_paths WHERE user_id=? AND book_file_id=?', (user_id, book_file_id))
        if row:
            row['parsed'] = _safe_json_loads(row.pop('parsed_json', '{}'), {})
        return row

    async def upsert_learning_path(self, user_id: str, book_file_id: str, *, source_file_id: str, source_name: str, content_md: str, parsed: dict, checksum: str) -> tuple[dict, bool]:
        existing = await self.get_learning_path(user_id, book_file_id)
        changed = not existing or str(existing.get('checksum') or '') != checksum
        now = _now()
        goal_ids = {str(item.get('id') or '') for item in parsed.get('goals') or []}
        phase_ids = {str(item.get('id') or '') for item in parsed.get('phases') or []}
        current_goal = str((existing or {}).get('current_goal_id') or '')
        current_phase = str((existing or {}).get('current_phase_id') or '')
        if current_goal not in goal_ids:
            current_goal = str(parsed.get('default_goal_id') or next(iter(goal_ids), 'default'))
        if current_phase not in phase_ids:
            phases = parsed.get('phases') or []
            current_phase = str(parsed.get('default_phase_id') or (phases[0] if phases else {}).get('id') or 'orientation')
        path_id = str((existing or {}).get('id') or uuid.uuid4())
        await self.execute('INSERT INTO learning_paths(id,user_id,book_file_id,source_file_id,source_name,checksum,name,version,content_md,parsed_json,current_goal_id,current_phase_id,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(user_id,book_file_id) DO UPDATE SET source_file_id=excluded.source_file_id,source_name=excluded.source_name,checksum=excluded.checksum,name=excluded.name,version=excluded.version,content_md=excluded.content_md,parsed_json=excluded.parsed_json,current_goal_id=excluded.current_goal_id,current_phase_id=excluded.current_phase_id,updated_at=excluded.updated_at', (path_id, user_id, book_file_id, source_file_id or None, source_name, checksum, str(parsed.get('name') or 'Učební cesta')[:200], str(parsed.get('version') or '1.0')[:40], content_md, _json_dumps(parsed), current_goal, current_phase, int((existing or {}).get('created_at') or now), now))
        result = await self.get_learning_path(user_id, book_file_id)
        return (result or {}, changed)

    async def update_learning_path_state(self, user_id: str, book_file_id: str, *, goal_id: str | None=None, phase_id: str | None=None) -> dict:
        path = await self.get_learning_path(user_id, book_file_id)
        if not path:
            raise HTTPException(status_code=404, detail='K této knize není přiřazena učební cesta.')
        parsed = path.get('parsed') or {}
        goals = {str(item.get('id') or '') for item in parsed.get('goals') or []}
        phases = {str(item.get('id') or '') for item in parsed.get('phases') or []}
        next_goal = str(path.get('current_goal_id') or '')
        next_phase = str(path.get('current_phase_id') or '')
        if goal_id is not None:
            if goal_id not in goals:
                raise HTTPException(status_code=400, detail='Vybraný pedagogický cíl není součástí šablony.')
            next_goal = goal_id
        if phase_id is not None:
            if phase_id not in phases:
                raise HTTPException(status_code=400, detail='Vybraná fáze není součástí šablony.')
            next_phase = phase_id
        await self.execute('UPDATE learning_paths SET current_goal_id=?,current_phase_id=?,updated_at=? WHERE user_id=? AND book_file_id=?', (next_goal, next_phase, _now(), user_id, book_file_id))
        return await self.get_learning_path(user_id, book_file_id) or {}

    async def remove_learning_path(self, user_id: str, book_file_id: str) -> None:
        await self.execute('DELETE FROM learning_paths WHERE user_id=? AND book_file_id=?', (user_id, book_file_id))

