    async def add_selection(self, user_id: str, session_id: str, file_id: str, page_index: int, text: str, rectangles: list[dict], *, linear_text: str='', latex_text: str='', latex_confidence: float=0.0, mathml_text: str='', context_before: str='', context_after: str='', glyphs: list[dict] | None=None, crop_path: str='', crop_mime: str='', transcription_quality: str='plain-text', selection_id: str | None=None) -> dict:
        selection_id = selection_id or str(uuid.uuid4())
        await self.execute('INSERT INTO selections(id,session_id,user_id,file_id,page_index,selected_text,linear_text,latex_text,latex_confidence,mathml_text,context_before,context_after,glyphs_json,crop_path,crop_mime,transcription_quality,rectangles_json,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)', (selection_id, session_id, user_id, file_id, max(0, page_index), text, linear_text, latex_text, max(0.0, min(1.0, float(latex_confidence or 0))), mathml_text, context_before, context_after, _json_dumps(glyphs or []), crop_path, crop_mime, transcription_quality, _json_dumps(rectangles), _now()))
        row = await self.one('SELECT * FROM selections WHERE id=?', (selection_id,)) or {}
        row['rectangles'] = _safe_json_loads(row.pop('rectangles_json', '[]'), [])
        row['glyphs'] = _safe_json_loads(row.pop('glyphs_json', '[]'), [])
        return row

    @staticmethod
    def _decode_selection_row(row: dict | None) -> dict | None:
        if not row:
            return None
        row = dict(row)
        row['rectangles'] = _safe_json_loads(row.pop('rectangles_json', '[]'), [])
        row['glyphs'] = _safe_json_loads(row.pop('glyphs_json', '[]'), [])
        return row

    async def get_selection(self, user_id: str, selection_id: str) -> dict | None:
        row = await self.one('SELECT * FROM selections WHERE id=? AND user_id=?', (selection_id, user_id))
        return self._decode_selection_row(row)

    async def last_selection(self, user_id: str, session_id: str) -> dict | None:
        row = await self.one('SELECT * FROM selections WHERE user_id=? AND session_id=? ORDER BY created_at DESC LIMIT 1', (user_id, session_id))
        return self._decode_selection_row(row)

    async def add_activity(self, user_id: str, session_id: str, file_id: str, activity_type: str, title: str, topic: str, payload: dict) -> dict:
        activity_id = str(uuid.uuid4())
        await self.execute('INSERT INTO activities(id,session_id,user_id,file_id,activity_type,title,topic,payload_json,created_at) VALUES(?,?,?,?,?,?,?,?,?)', (activity_id, session_id, user_id, file_id, activity_type, title, topic, _json_dumps(payload), _now()))
        return await self.get_activity(user_id, activity_id) or {}

    async def get_activity(self, user_id: str, activity_id: str) -> dict | None:
        row = await self.one('SELECT * FROM activities WHERE id=? AND user_id=?', (activity_id, user_id))
        if row:
            row['payload'] = _safe_json_loads(row.pop('payload_json', '{}'), {})
        return row

    async def list_activities(self, user_id: str, session_id: str, limit: int=20) -> list[dict]:
        rows = await self.all('SELECT * FROM activities WHERE user_id=? AND session_id=? ORDER BY created_at DESC LIMIT ?', (user_id, session_id, max(1, min(limit, 100))))
        for row in rows:
            row['payload'] = _safe_json_loads(row.pop('payload_json', '{}'), {})
        return rows

    async def add_attempt(self, user_id: str, activity_id: str, answers: dict, result: dict, score: float) -> dict:
        attempt_id = str(uuid.uuid4())
        await self.execute('INSERT INTO attempts(id,activity_id,user_id,answers_json,result_json,score,created_at) VALUES(?,?,?,?,?,?,?)', (attempt_id, activity_id, user_id, _json_dumps(answers), _json_dumps(result), score, _now()))
        row = await self.one('SELECT * FROM attempts WHERE id=?', (attempt_id,))
        if row:
            row['answers'] = _safe_json_loads(row.pop('answers_json', '{}'), {})
            row['result'] = _safe_json_loads(row.pop('result_json', '{}'), {})
        return row or {}

    async def last_attempt_for_activity(self, user_id: str, activity_id: str) -> dict | None:
        row = await self.one('SELECT * FROM attempts WHERE user_id=? AND activity_id=? ORDER BY created_at DESC LIMIT 1', (user_id, activity_id))
        if row:
            row['answers'] = _safe_json_loads(row.pop('answers_json', '{}'), {})
            row['result'] = _safe_json_loads(row.pop('result_json', '{}'), {})
        return row

    async def update_mastery(self, user_id: str, file_id: str, topic_name: str, score: float) -> dict:
        topic_name = (topic_name or 'Studované téma').strip()[:200]
        topic_key = hashlib.sha256(topic_name.casefold().encode('utf-8')).hexdigest()[:24]
        old = await self.one('SELECT * FROM mastery WHERE user_id=? AND file_id=? AND topic_key=?', (user_id, file_id, topic_key))
        score = max(0.0, min(1.0, float(score)))
        if old:
            count = int(old['evidence_count']) + 1
            mastery = max(0.0, min(1.0, float(old['mastery']) * 0.72 + score * 0.28))
            await self.execute('UPDATE mastery SET topic_name=?,mastery=?,evidence_count=?,updated_at=? WHERE user_id=? AND file_id=? AND topic_key=?', (topic_name, mastery, count, _now(), user_id, file_id, topic_key))
        else:
            mastery = 0.25 + score * 0.45
            count = 1
            await self.execute('INSERT INTO mastery(user_id,file_id,topic_key,topic_name,mastery,evidence_count,updated_at) VALUES(?,?,?,?,?,?,?)', (user_id, file_id, topic_key, topic_name, mastery, count, _now()))
        return {'topic_key': topic_key, 'topic_name': topic_name, 'mastery': mastery, 'evidence_count': count}

    async def list_mastery(self, user_id: str, file_id: str) -> list[dict]:
        return await self.all('SELECT * FROM mastery WHERE user_id=? AND file_id=? ORDER BY mastery ASC,updated_at DESC', (user_id, file_id))

