            parameters = spec.get('parameters') if isinstance(spec.get('parameters'), dict) else {}
            provider_hint = ' '.join((str(value or '') for value in (tool_id, installed_name, raw.get('type'), declared_name, description, metadata.get('vut_ai_server_url'), metadata.get('vut_ai_connection_id'), deferred.get('connection_url'), deferred.get('connection_id'), server.get('url'), server.get('name'))))
