            @router.get('/assets/{folder}/{name:path}')
            async def pdf_asset_compat(folder: str, name: str):
                if folder not in {'cmaps', 'standard_fonts', 'wasm', 'iccs', 'images'}:
                    raise HTTPException(status_code=404, detail='Asset nebyl nalezen.')
                if not name or '..' in name or (not re.fullmatch('[A-Za-z0-9_.\\-/]+', name)):
                    raise HTTPException(status_code=400, detail='Neplatný název assetu.')
                relative = f'web/images/{name}' if folder == 'images' else f'{folder}/{name}'
                path = await self.pdfjs_asset(relative)
                return FileResponse(path, media_type=_pdfjs_media_type(relative), headers={**_cors_headers(), 'Cache-Control': 'public, max-age=31536000, immutable'})

