            @router.post('/api/selection-actions')
            async def queue_selection_action(request: Request, form: SelectionActionQueueForm):
                claims = await self.claims_from_request(request)
                user = await self.user_from_claims(claims)
                session_id = str(claims.get('sid') or '')
                if form.session_id and form.session_id != session_id:
                    raise HTTPException(status_code=409, detail='Výběr patří k jiné studijní relaci.')
                session = await self.db.get_session(user.id, session_id)
                if not session:
                    raise HTTPException(status_code=404, detail='Studijní relace už není dostupná.')
                selection = await self.db.get_selection(user.id, form.selection_id)
                if not selection:
                    raise HTTPException(status_code=404, detail='Označená pasáž už není dostupná.')
                if str(selection.get('session_id') or '') != session_id:
                    raise HTTPException(status_code=409, detail='Označená pasáž patří k jiné relaci.')
                if form.file_id and str(selection.get('file_id') or '') != form.file_id:
                    raise HTTPException(status_code=409, detail='Označená pasáž patří k jiné knize.')
                with suppress(Exception):
                    await self.db.execute('DELETE FROM pending_tool_actions WHERE user_id=? AND session_id=? AND consumed_at=0', (user.id, session_id))
                    await self.db.execute("UPDATE tool_action_threads SET state='cancelled',updated_at=? WHERE user_id=? AND session_id=? AND state='awaiting_user'", (_now(), user.id, session_id))
                payload = {'v': '1', 'action': form.action, 'selection_id': form.selection_id, 'file_id': form.file_id or str(selection.get('file_id') or session.get('file_id') or ''), 'session_id': session_id, 'page': str(form.page)}
                binding_id = await self.db.queue_prompt_binding(user.id, str(session.get('chat_id') or ''), session_id, form.prompt, 'selection', payload)
                return self._response_json({'ok': True, 'binding_id': binding_id, 'expires_in': 240}, 201)

            @router.post('/api/tool-actions')
            async def queue_tool_action(request: Request, form: ToolActionQueueForm):
                claims = await self.claims_from_request(request)
                user = await self.user_from_claims(claims)
                session_id = str(claims.get('sid') or '')
                if form.session_id and form.session_id != session_id:
                    raise HTTPException(status_code=409, detail='Požadavek nástroje patří k jiné studijní relaci.')
                session = await self.db.get_session(user.id, session_id)
                if not session:
                    raise HTTPException(status_code=404, detail='Studijní relace už není dostupná.')
                tool_state = await self.db.get_session_tool_state(user.id, session_id)
                catalog = tool_state.get('catalog') or []
                inventory = tool_state.get('inventory') or []
                exact = next((item for item in inventory if str(item.get('function_name') or item.get('declared_name') or '') == form.function_name and (not form.tool_id or str(item.get('tool_id') or '') == form.tool_id) and bool(item.get('invocable')) and (str(item.get('availability') or '') != 'awaiting-next-turn')), None)
                if not exact:
                    exact = next((item for item in catalog if (str(item.get('function_name') or '') == form.function_name or (form.workflow_kind and str(item.get('workflow_kind') or '') == form.workflow_kind)) and (not form.tool_id or str(item.get('tool_id') or '') == form.tool_id or (form.origin_key and str(item.get('origin_key') or '') == form.origin_key) or bool(set(form.origin_aliases or []) & set(item.get('origin_aliases') or []))) and (item.get('verified') is True)), None)
                if not exact:
                    raise HTTPException(status_code=409, detail='Tato přesná funkce už není v živém katalogu aktuálního Canvasu. Pokud jste ji právě zapnuli, odešlete jednu zprávu nebo použijte Prohledat Workspace.')
                if form.selection_id:
                    selection = await self.db.get_selection(user.id, form.selection_id)
                    if not selection:
                        raise HTTPException(status_code=404, detail='Označená pasáž už není dostupná.')
                    if str(selection.get('session_id') or '') != session_id:
                        raise HTTPException(status_code=409, detail='Označená pasáž patří k jiné relaci.')
                    if form.file_id and str(selection.get('file_id') or '') != form.file_id:
                        raise HTTPException(status_code=409, detail='Označená pasáž patří k jiné knize.')
                payload = {'v': '4-exact-provider-lock', 'function': form.function_name, 'tool_id': form.tool_id or str(exact.get('tool_id') or ''), 'capability': form.capability or str(exact.get('capability') or 'generic'), 'provider': form.provider or str(exact.get('provider') or 'generic'), 'installed_name': form.installed_name or str(exact.get('installed_name') or ''), 'workflow_kind': form.workflow_kind or str(exact.get('workflow_kind') or ''), 'ansys_product': form.ansys_product or str(exact.get('ansys_product') or ''), 'preferred_function': form.preferred_function or str(exact.get('preferred_function') or ''), 'preferred_operation': str(exact.get('preferred_operation') or ''), 'origin_key': form.origin_key or str(exact.get('origin_key') or ''), 'origin_url': form.origin_url or str(exact.get('origin_url') or ''), 'origin_aliases': list(dict.fromkeys([*(form.origin_aliases or []), *(exact.get('origin_aliases') or [])]))[:32], 'candidate_operations': list(dict.fromkeys([*(form.candidate_operations or []), *(exact.get('candidate_operations') or [])]))[:64], 'candidate_functions': list(dict.fromkeys([*(form.candidate_functions or []), *(exact.get('candidate_functions') or [])]))[:64], 'strict_exact': bool(form.strict_exact), 'lifecycle_function': str(exact.get('lifecycle_function') or ''), 'lifecycle_operation': str(exact.get('lifecycle_operation') or ''), 'selection_id': form.selection_id, 'file_id': form.file_id or str(session.get('file_id') or ''), 'session_id': session_id, 'page': str(form.page)}
                await self.db.execute("UPDATE tool_action_threads SET state='cancelled',updated_at=? WHERE user_id=? AND session_id=? AND state='awaiting_user'", (_now(), user.id, session_id))
                action_id = await self.db.queue_tool_action(user.id, str(session.get('chat_id') or ''), session_id, form.prompt, payload, ttl_seconds=1800)
                log.info('VUT AI Tutor queued tool action action=%s session=%s tool=%s function=%s capability=%s', action_id[:8], session_id[:8], form.tool_id, form.function_name, payload['capability'])
                return self._response_json({'ok': True, 'action_id': action_id, 'expires_in': 1800}, 201)

            @router.post('/api/upload')
            async def upload_book(request: Request, background_tasks: BackgroundTasks, file: UploadFile=File(...)):
                claims = await self.claims_from_request(request)
                user = await self.user_from_claims(claims)
                if not file.filename:
                    raise HTTPException(status_code=400, detail='Soubor nemá název.')
                if not file.filename.lower().endswith('.pdf') and file.content_type != 'application/pdf':
                    raise HTTPException(status_code=400, detail='VUT AI Tutor podporuje v této verzi knihy ve formátu PDF.')
                knowledge_id = await self.ensure_knowledge(user.id)
                from open_webui.routers.files import upload_file_handler
                result = await upload_file_handler(request, file=file, metadata={'knowledge_id': knowledge_id, 'study_tutor': True}, process=False, process_in_background=False, user=user, background_tasks=background_tasks)
                payload = _model_dump(result)
                file_id = str(payload.get('id') or '')
                if not file_id:
                    raise HTTPException(status_code=500, detail='Open WebUI nevrátilo identifikátor nahraného souboru.')
                meta = _model_dump(payload.get('meta'))
                title = _normalize_title(meta.get('name') or payload.get('filename') or file.filename)
                book = await self.db.register_book(user.id, knowledge_id, file_id, title, str(meta.get('file_hash') or ''))
                canonical_file_id = str(book.get('file_id') or file_id)
                await self.db.update_session_file(user.id, claims['sid'], canonical_file_id)
                if not book.get('deduplicated'):
                    self.schedule_safe_index(request, user, book)
                return self._response_json({'file_id': canonical_file_id, 'knowledge_id': knowledge_id, 'title': str(book.get('title') or title), 'status': 'completed' if book.get('deduplicated') else 'processing', 'analysis_status': 'cached' if book.get('deduplicated') else 'pending', 'deduplicated': bool(book.get('deduplicated'))}, 200 if book.get('deduplicated') else 201)

