            @router.post('/api/demo/install')
            async def install_demo_book(request: Request, background_tasks: BackgroundTasks):
                claims = await self.claims_from_request(request)
                user = await self.user_from_claims(claims)
                for book in await self.db.list_books(user.id):
                    if book.get('title') == DEMO_BOOK_TITLE:
                        await self.db.set_setting(user.id, 'active_file_id', book['file_id'])
                        await self.db.update_session_file(user.id, claims['sid'], book['file_id'])
                        status, error = await self.file_status(book['file_id'])
                        return self._response_json({'file_id': book['file_id'], 'knowledge_id': book['knowledge_id'], 'title': DEMO_BOOK_TITLE, 'status': status, 'error': error, 'reused': True, 'source_url': DEMO_BOOK_PAGE, 'license': DEMO_BOOK_LICENSE})
                try:
                    temp_path, size = await asyncio.to_thread(self._download_demo_pdf)
                except Exception as exc:
                    raise HTTPException(status_code=503, detail=f'Ukázkovou knihu se nepodařilo stáhnout z oficiálního zdroje. Zkontrolujte připojení k internetu nebo nahrajte vlastní PDF. Podrobnost: {exc}') from exc
                demo_upload = UploadFile(file=temp_path.open('rb'), size=size, filename=DEMO_BOOK_FILENAME, headers=Headers({'content-type': 'application/pdf'}))
                try:
                    knowledge_id = await self.ensure_knowledge(user.id)
                    from open_webui.routers.files import upload_file_handler
                    result = await upload_file_handler(request, file=demo_upload, metadata={'knowledge_id': knowledge_id, 'study_tutor': True, 'study_tutor_demo': True, 'title': DEMO_BOOK_TITLE, 'author': DEMO_BOOK_AUTHOR, 'source_url': DEMO_BOOK_PAGE, 'download_url': DEMO_BOOK_URL, 'license': DEMO_BOOK_LICENSE}, process=False, process_in_background=False, user=user, background_tasks=background_tasks)
                    payload = _model_dump(result)
                    file_id = str(payload.get('id') or '')
                    if not file_id:
                        raise HTTPException(status_code=500, detail='Open WebUI nevrátilo identifikátor ukázkové knihy.')
                    meta = _model_dump(payload.get('meta'))
                    book = await self.db.register_book(user.id, knowledge_id, file_id, DEMO_BOOK_TITLE, str(meta.get('file_hash') or ''))
                    canonical_file_id = str(book.get('file_id') or file_id)
                    await self.db.update_session_file(user.id, claims['sid'], canonical_file_id)
                    if not book.get('deduplicated'):
                        self.schedule_safe_index(request, user, book)
                    background_tasks.add_task(self._cleanup_demo_upload, str(temp_path), demo_upload)
                    return self._response_json({'file_id': canonical_file_id, 'knowledge_id': knowledge_id, 'title': str(book.get('title') or DEMO_BOOK_TITLE), 'status': 'completed' if book.get('deduplicated') else 'processing', 'reused': bool(book.get('deduplicated')), 'source_url': DEMO_BOOK_PAGE, 'license': DEMO_BOOK_LICENSE}, 201)
                except Exception:
                    with suppress(Exception):
                        await demo_upload.close()
                    with suppress(Exception):
                        temp_path.unlink()
                    raise

