            @router.get('/api/pdf/{file_id}')
            async def get_pdf(request: Request, file_id: str):
                claims = await self.claims_from_request(request)
                file_item, _ = await self._get_file(claims['uid'], file_id)
                from open_webui.storage.provider import Storage
                file_path = Path(await asyncio.to_thread(Storage.get_file, file_item.path))
                if not file_path.is_file():
                    raise HTTPException(status_code=404, detail='Originální PDF nebylo nalezeno v úložišti.')
                title = getattr(file_item, 'filename', 'book.pdf') or 'book.pdf'
                encoded = urllib.parse.quote(title)
                common_headers = {**_cors_headers(), 'Content-Disposition': f"inline; filename*=UTF-8''{encoded}", 'Cache-Control': 'private, max-age=300', 'Accept-Ranges': 'bytes', 'X-Content-Type-Options': 'nosniff'}
                size = file_path.stat().st_size
                range_header = request.headers.get('range', '').strip()
                if not range_header:
                    return FileResponse(file_path, media_type='application/pdf', headers=common_headers)
                match = re.fullmatch('bytes=(\\d*)-(\\d*)', range_header)
                if not match or ',' in range_header:
                    return Response(status_code=416, headers={**common_headers, 'Content-Range': f'bytes */{size}'})
                start_text, end_text = match.groups()
                if not start_text and (not end_text):
                    return Response(status_code=416, headers={**common_headers, 'Content-Range': f'bytes */{size}'})
                if start_text:
                    start = int(start_text)
                    end = int(end_text) if end_text else size - 1
                else:
                    suffix = int(end_text)
                    if suffix <= 0:
                        return Response(status_code=416, headers={**common_headers, 'Content-Range': f'bytes */{size}'})
                    start = max(0, size - suffix)
                    end = size - 1
                if start >= size or start < 0 or end < start:
                    return Response(status_code=416, headers={**common_headers, 'Content-Range': f'bytes */{size}'})
                end = min(end, size - 1)
                length = end - start + 1

                async def stream_range():
                    with file_path.open('rb') as handle:
                        handle.seek(start)
                        remaining = length
                        while remaining > 0:
                            chunk = await asyncio.to_thread(handle.read, min(1024 * 1024, remaining))
                            if not chunk:
                                break
                            remaining -= len(chunk)
                            yield chunk
                return StreamingResponse(stream_range(), status_code=206, media_type='application/pdf', headers={**common_headers, 'Content-Range': f'bytes {start}-{end}/{size}', 'Content-Length': str(length)})

