            @router.get('/api/concepts/{concept_id}')
            async def concept_detail(request: Request, concept_id: str):
                claims = await self.claims_from_request(request)
                active = await self.get_active_book(claims['uid'], claims.get('sid'))
                if not active:
                    raise HTTPException(status_code=400, detail='Nejprve otevřete knihu.')
                row = await self.db.get_analysis(claims['uid'], active['file_id'])
                graph, _ = self.active_analysis_graph(row)
                concept = next((c for c in graph.get('concepts') or [] if c.get('id') == concept_id), None)
                if not concept:
                    raise HTTPException(status_code=404, detail='Pojem nebyl nalezen.')
                edges = [e for e in graph.get('edges') or [] if concept_id in {e.get('source'), e.get('target')}]
                neighbors = []
                by_id = {c['id']: c for c in graph.get('concepts') or []}
                for edge in edges[:40]:
                    other = edge['target'] if edge['source'] == concept_id else edge['source']
                    if other in by_id:
                        neighbors.append({'id': other, 'name': by_id[other]['name'], 'relation': edge.get('type') or 'souvisí s', 'weight': edge.get('weight') or 1})
                return self._response_json({'concept': concept, 'neighbors': neighbors})

