            @router.post('/api/toc/import')
            async def import_toc(request: Request, form: TocImportForm):
                claims = await self.claims_from_request(request)
                active = await self.get_active_book(claims['uid'], claims.get('sid'))
                if not active:
                    raise HTTPException(status_code=400, detail='Nejprve otevřete knihu.')
                total_pages = max(0, int(form.total_pages or 0))
                cleaned: list[dict[str, Any]] = []
                known_ids: set[str] = set()
                for index, raw in enumerate(form.items[:3000]):
                    if not isinstance(raw, dict):
                        continue
                    title = re.sub('\\s+', ' ', str(raw.get('title') or '')).strip()[:500]
                    if not title:
                        continue
                    try:
                        page = int(raw.get('page') or 0)
                    except Exception:
                        page = 0
                    if page < 0 or (total_pages and page > total_pages):
                        page = 0
                    try:
                        level = max(0, min(20, int(raw.get('level') or 0)))
                    except Exception:
                        level = 0
                    source_id = re.sub('[^A-Za-z0-9_.:-]', '-', str(raw.get('id') or ''))[:180]
                    item_id = source_id or f'pdf-outline-{index + 1}'
                    if item_id in known_ids:
                        item_id = f'{item_id}-{index + 1}'
                    known_ids.add(item_id)
                    parent_id = re.sub('[^A-Za-z0-9_.:-]', '-', str(raw.get('parent_id') or ''))[:180] or None
                    cleaned.append({'id': item_id, 'parent_id': parent_id, 'level': level, 'title': title, 'page': page or None, 'page_label': re.sub('\\s+', ' ', str(raw.get('page_label') or '')).strip()[:80], 'source': 'pdf-outline-browser'})
                if not cleaned:
                    return self._response_json({'ok': True, 'stored': 0})
                existing = await self.db.get_analysis(claims['uid'], active['file_id'])
                current_toc = (existing or {}).get('toc') or []
                use_import = not current_toc or all((item.get('source') != 'pdf-outline' for item in current_toc))
                if use_import:
                    await self.db.set_analysis(claims['uid'], active['file_id'], status=str((existing or {}).get('status') or 'processing'), progress=float((existing or {}).get('progress') or 0.12), stage=str((existing or {}).get('stage') or 'Interaktivní obsah byl načten z PDF'), graph=(existing or {}).get('graph') or {}, toc=cleaned, error=(existing or {}).get('error'))
                return self._response_json({'ok': True, 'stored': len(cleaned) if use_import else 0})

